-- Zimam's status model: widen, map the old statuses, then narrow
ALTER TABLE `orders` MODIFY COLUMN `status` enum('new','confirmed','cancelled','callback','no_answer','voicemail','fake','wrong_number','duplicate','remark','shipped','delivered','returned','pending','call_back','in_transit','abandoned','flagged') NOT NULL DEFAULT 'pending';--> statement-breakpoint
UPDATE `orders` SET `status` = CASE `status` WHEN 'new' THEN 'pending' WHEN 'remark' THEN 'pending' WHEN 'callback' THEN 'call_back' WHEN 'no_answer' THEN 'call_back' WHEN 'voicemail' THEN 'call_back' WHEN 'wrong_number' THEN 'cancelled' WHEN 'duplicate' THEN 'cancelled' WHEN 'fake' THEN 'flagged' WHEN 'shipped' THEN 'in_transit' ELSE `status` END;--> statement-breakpoint
UPDATE `order_events` SET `from_status` = CASE `from_status` WHEN 'new' THEN 'pending' WHEN 'remark' THEN 'pending' WHEN 'callback' THEN 'call_back' WHEN 'no_answer' THEN 'call_back' WHEN 'voicemail' THEN 'call_back' WHEN 'wrong_number' THEN 'cancelled' WHEN 'duplicate' THEN 'cancelled' WHEN 'fake' THEN 'flagged' WHEN 'shipped' THEN 'in_transit' ELSE `from_status` END WHERE `from_status` IS NOT NULL;--> statement-breakpoint
UPDATE `order_events` SET `to_status` = CASE `to_status` WHEN 'new' THEN 'pending' WHEN 'remark' THEN 'pending' WHEN 'callback' THEN 'call_back' WHEN 'no_answer' THEN 'call_back' WHEN 'voicemail' THEN 'call_back' WHEN 'wrong_number' THEN 'cancelled' WHEN 'duplicate' THEN 'cancelled' WHEN 'fake' THEN 'flagged' WHEN 'shipped' THEN 'in_transit' ELSE `to_status` END WHERE `to_status` IS NOT NULL;--> statement-breakpoint
UPDATE `order_events` SET `type` = 'note' WHERE `type` IN ('followup','call');--> statement-breakpoint
-- Abandoned carts become orders with the status "abandoned" (numbers continue each shop's sequence)
INSERT INTO `orders` (`id`, `shop_id`, `number`, `status`, `customer_name`, `phone`, `wilaya_code`, `commune`, `delivery_type`, `subtotal`, `shipping_price`, `total`, `ip`, `created_at`) SELECT l.`id`, l.`shop_id`, COALESCE(m.`mx`, 1000) + ROW_NUMBER() OVER (PARTITION BY l.`shop_id` ORDER BY l.`created_at`, l.`id`), 'abandoned', COALESCE(l.`name`, ''), l.`phone`, COALESCE(l.`wilaya_code`, 0), '', 'home', COALESCE(v.`price`, p.`price`) * l.`quantity`, 0, COALESCE(v.`price`, p.`price`) * l.`quantity`, l.`ip`, l.`created_at` FROM `leads` l JOIN `products` p ON p.`id` = l.`product_id` AND p.`shop_id` = l.`shop_id` LEFT JOIN `product_variants` v ON v.`id` = l.`variant_id` LEFT JOIN (SELECT `shop_id`, MAX(`number`) AS `mx` FROM `orders` GROUP BY `shop_id`) m ON m.`shop_id` = l.`shop_id` WHERE l.`status` IN ('abandoned','contacted') AND NOT EXISTS (SELECT 1 FROM `orders` x WHERE x.`id` = l.`id`);--> statement-breakpoint
INSERT INTO `order_items` (`id`, `order_id`, `shop_id`, `product_id`, `variant_id`, `name`, `variant_title`, `unit_price`, `quantity`, `total`, `stock_tracked`) SELECT UUID(), l.`id`, l.`shop_id`, l.`product_id`, v.`id`, p.`name`, v.`title`, COALESCE(v.`price`, p.`price`), l.`quantity`, COALESCE(v.`price`, p.`price`) * l.`quantity`, false FROM `leads` l JOIN `orders` o ON o.`id` = l.`id` AND o.`status` = 'abandoned' JOIN `products` p ON p.`id` = l.`product_id` LEFT JOIN `product_variants` v ON v.`id` = l.`variant_id` WHERE NOT EXISTS (SELECT 1 FROM `order_items` i WHERE i.`order_id` = l.`id`);--> statement-breakpoint
INSERT INTO `order_events` (`id`, `order_id`, `shop_id`, `type`, `to_status`, `created_at`) SELECT UUID(), l.`id`, l.`shop_id`, 'created', 'abandoned', l.`created_at` FROM `leads` l JOIN `orders` o ON o.`id` = l.`id` AND o.`status` = 'abandoned' WHERE NOT EXISTS (SELECT 1 FROM `order_events` e WHERE e.`order_id` = l.`id`);--> statement-breakpoint
DROP TABLE `leads`;--> statement-breakpoint
ALTER TABLE `order_events` MODIFY COLUMN `type` enum('created','status','note','edit','assign','message','risk') NOT NULL;--> statement-breakpoint
ALTER TABLE `orders` MODIFY COLUMN `status` enum('pending','confirmed','call_back','in_transit','delivered','returned','abandoned','cancelled','flagged') NOT NULL DEFAULT 'pending';--> statement-breakpoint
ALTER TABLE `orders` ADD `note` varchar(500);--> statement-breakpoint
ALTER TABLE `orders` ADD `shipping_waived` boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE `orders` ADD `carrier_account_id` varchar(36);
